class Solution { public int maxLevelSum(TreeNode root){Queue<TreeNode> queue=new ArrayDeque<>();queue.offer(root);int level=0,bestLevel=0,bestSum=Integer.MIN_VALUE;while(!queue.isEmpty()){level++;int size=queue.size(),sum=0;while(size-->0){TreeNode node=queue.poll();sum+=node.val;if(node.left!=null)queue.offer(node.left);if(node.right!=null)queue.offer(node.right);}if(sum>bestSum){bestSum=sum;bestLevel=level;}}return bestLevel;} }
